package local.proskurnin.preview;
import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class LocalWatchActivity extends VoiceActivity {
 void submit(){}
 void phoneQuery(){}
 LinearLayout list;Button toggle;LocalWatchStore.Job job;String from="",to="";
 public void onCreate(Bundle state){super.onCreate(state);from=getIntent().getStringExtra("from");to=getIntent().getStringExtra("to");if(from==null)from="";if(to==null)to="";
  LinearLayout root=base("История приложений","ТОЛЬКО НА ЭТОМ ТВ");TextView note=label("Записи приложений не означают, что фильм досмотрен. Старые записи без даты не попадают в выборку за неделю.",15);root.addView(note);
  LinearLayout actions=new LinearLayout(this);root.addView(actions);toggle=button("");Button update=button("Обновить"),sources=button("Источники"),clear=button("Очистить"),back=button("Назад");for(Button b:new Button[]{toggle,update,sources,clear,back})actions.addView(b,new LinearLayout.LayoutParams(0,dp(42),1));
  toggle.setOnClickListener(v->{if(job!=null)job.cancel();boolean next=!LocalWatchStore.enabled(this);getSharedPreferences("preview",0).edit().putBoolean("local_watch_enabled",next).apply();render();if(next)refresh();});update.setOnClickListener(v->refresh());sources.setOnClickListener(v->sources());clear.setOnClickListener(v->new LauncherDialogs.Builder(this).setTitle("Остановить сбор и очистить импортированные записи?").setMessage("Ручные отметки и история в самих кинотеатрах сохранятся. Повторное включение сбора импортирует доступные записи заново.").setPositiveButton("Очистить",(d,n)->{if(job!=null)job.cancel();synchronized(LocalWatchStore.WRITE_LOCK){getSharedPreferences("preview",0).edit().putBoolean("local_watch_enabled",false).remove(LocalWatchStore.KEY).remove("local_watch_error").apply();}render();}).setNegativeButton("Отмена",null).show());back.setOnClickListener(v->finish());
  status=label("",14);root.addView(status);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));render();update.requestFocus();
 }
 void refresh(){if(job!=null)job.cancel();if(!LocalWatchStore.enabled(this)){render();return;}status.setText("Обновляю локальные записи…");job=LocalWatchStore.refresh(this,()->{if(alive)render();});}
 void sources(){JSONObject data=LocalWatchStore.saved(this);JSONArray sources=data.optJSONArray("sources");StringBuilder text=new StringBuilder();if(sources!=null)for(int i=0;i<sources.length();i++){JSONObject s=sources.optJSONObject(i);if(s!=null)text.append(LocalWatchStore.name(s.optString("package"))).append(": ").append(LocalWatchStore.state(s.optString("status"))).append(" · ").append(s.optInt("count")).append("\n\n");}if(text.length()==0)text.append("Данных помощника пока нет. На этой модели может отсутствовать доступ к локальным источникам.");new LauncherDialogs.Builder(this).setTitle("Все восемь кинотеатров").setMessage(text.toString()).setPositiveButton("Закрыть",null).show();}
 boolean matches(JSONObject r){String date=LocalWatchStore.date(r);return from.isEmpty()||(!date.isEmpty()&&date.compareTo(from)>=0&&date.compareTo(to)<=0);}
 void render(){if(list==null)return;toggle.setEnabled(LocalWatchStore.supported());toggle.setText(LocalWatchStore.enabled(this)?"Сбор: вкл":"Сбор: выкл");list.removeAllViews();JSONObject data=LocalWatchStore.saved(this);JSONArray rows=data.optJSONArray("items");ArrayList<JSONObject> visible=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&matches(r))visible.add(r);}visible.sort((a,b)->Long.compare(b.optLong("reported_at"),a.optLong("reported_at")));
  int count=0;for(JSONObject row:visible){if(count++>=300)break;Button b=button(LocalWatchStore.name(row.optString("package"))+" · "+row.optString("title")+"\n"+LocalWatchStore.evidence(row));b.setTextSize(14);b.setSingleLine(false);list.addView(b,new LinearLayout.LayoutParams(-1,dp(66)));b.setOnClickListener(v->new LauncherDialogs.Builder(this).setTitle(row.optString("title")).setMessage(LocalWatchStore.evidence(row)+"\n\nЗапись сохранена локально. Она не устанавливает ручную отметку «Смотрел».").setPositiveButton("Найти фильм",(d,n)->startActivity(new Intent(this,MovieActivity.class).putExtra("phone_query",row.optString("title")).putExtra("cinema_package",row.optString("package")))).setNegativeButton("Назад",null).show());}
  if(!from.isEmpty()){try{WatchPeriod period=new WatchPeriod(java.time.LocalDate.parse(from),java.time.LocalDate.parse(to));JSONArray manual=new MovieHistory(getSharedPreferences("preview",0)).during(period);for(int i=0;i<manual.length();i++){JSONObject m=manual.getJSONObject(i);TextView t=label("Ваша отметка · "+m.optString("title")+"\n"+m.optString("reason"),16);list.addView(t);}}catch(Exception ignored){}}
  String error=getSharedPreferences("preview",0).getString("local_watch_error","");status.setText(!LocalWatchStore.supported()?"На этом профиле локальный помощник пока недоступен":!error.isEmpty()?error:(from.isEmpty()?"Импортированных записей: "+visible.size():from+" — "+to+" · записей приложений: "+visible.size()));if(visible.isEmpty())list.addView(label("Подходящих записей приложений нет. Это не означает отсутствие просмотров.",16));
 }
 protected void onResume(){super.onResume();refresh();}
 protected void onPause(){if(job!=null)job.cancel();super.onPause();}
}
